  /* ── drivers: scroll (pinned, with autodrift), play (a clock, with controls), record, still ── */
  drivers() {
    const R = this.root;
    R.classList.add('is-' + this.driver);
    if (this.still) {
      R.classList.add('is-still'); R.style.height = '';
